// src/lib/openai.ts
// Readings are generated by the oracleReply Cloud Function (functions/src/oracle.ts), which
// holds the OpenAI key and prompt and checks the user's plan before answering. This file
// streams its reply into the app. Mock mode (MODE=mock) answers locally for development.
import { fetch as expoFetch } from 'expo/fetch';
import { extra, isMock } from './env';
import { getIdToken } from './auth';

export type ChatMessage = { role: 'user' | 'assistant'; content: string };

const FIRST_BYTE_TIMEOUT_MS = 30000;

// Thrown when no reading came back (network, server or OpenAI failure). Callers should show an
// error and must not treat it as a reply: it isn't saved and doesn't use up the free reading.
export class ReadingFailedError extends Error {
  constructor(reason: string) {
    super(reason);
    this.name = 'ReadingFailedError';
  }
}

// Thrown when the server says the free reading is used and there's no active plan.
export class PaymentRequiredError extends Error {
  constructor() {
    super('payment_required');
    this.name = 'PaymentRequiredError';
  }
}

function oracleUrl(): string {
  return extra.ORACLE_URL || `https://us-central1-${extra.FIREBASE_PROJECT_ID}.cloudfunctions.net/oracleReply`;
}

type StreamOptions = {
  // Called with each new chunk of text and the full text so far.
  onDelta?: (delta: string, fullText: string) => void;
  signal?: AbortSignal;
};

function mockReading(topic?: string) {
  const lines = [
    'Card: The Sun ☀️',
    '',
    `Warm clarity and joyful momentum surround you${topic ? ` in matters of ${topic}` : ''}.`,
    'Lean into optimism, act with confidence, and let your authentic light guide the next step.',
    '',
    'Trust the signs. The answers are already within you.',
  ];
  return lines.join('\n');
}

// Streams the mock reading word by word so the UI behaves like the real thing.
async function streamMock(text: string, { onDelta, signal }: StreamOptions): Promise<string> {
  let full = '';
  const tokens = text.match(/\S+\s*|\n/g) || [text];
  for (const token of tokens) {
    if (signal?.aborted) break;
    await new Promise((resolve) => setTimeout(resolve, 35));
    full += token;
    onDelta?.(token, full);
  }
  return full;
}

// Parses one SSE event block relayed by the function and returns any text delta.
function parseEvent(block: string): { delta?: string; done?: boolean; error?: string } {
  const data = block
    .split('\n')
    .filter((line) => line.startsWith('data:'))
    .map((line) => line.slice(5).trim())
    .join('');
  if (!data || data === '[DONE]') return {};

  let event: any;
  try {
    event = JSON.parse(data);
  } catch {
    return {};
  }

  switch (event?.type) {
    case 'response.output_text.delta':
      return { delta: event.delta ?? '' };
    case 'response.completed':
    case 'response.incomplete':
      return { done: true };
    case 'response.failed':
      return { error: event.response?.error?.message || 'response.failed' };
    case 'error':
      return { error: event.message || 'stream error' };
    default:
      return {};
  }
}

// Core reply, streamed. Resolves with the reply text (a reading cut short still counts, as the
// server does). Throws PaymentRequiredError for the paywall and ReadingFailedError otherwise.
export async function streamTarotReply(
  userMessages: ChatMessage[],
  options: StreamOptions = {}
): Promise<string> {
  if (isMock()) {
    const lastUser = userMessages.slice().reverse().find((m) => m.role === 'user')?.content || '';
    return streamMock(mockReading(lastUser.slice(0, 40)), options);
  }

  const token = await getIdToken();
  if (!token) {
    throw new ReadingFailedError('no signed-in user');
  }

  const controller = new AbortController();
  options.signal?.addEventListener('abort', () => controller.abort());
  const timeoutId = setTimeout(() => {
    console.warn('streamTarotReply: No response after 30 seconds, aborting...');
    controller.abort();
  }, FIRST_BYTE_TIMEOUT_MS);

  let full = '';
  try {
    const res = await expoFetch(oracleUrl(), {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
        Accept: 'text/event-stream',
      },
      body: JSON.stringify({ messages: userMessages.map(({ role, content }) => ({ role, content })) }),
      signal: controller.signal,
    });
    clearTimeout(timeoutId);

    if (res.status === 402) throw new PaymentRequiredError();
    if (!res.ok || !res.body) {
      throw new ReadingFailedError(`oracle returned ${res.status}: ${await res.text()}`);
    }

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';

    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true }).replace(/\r\n/g, '\n');

      let boundary = buffer.indexOf('\n\n');
      while (boundary !== -1) {
        const event = parseEvent(buffer.slice(0, boundary));
        buffer = buffer.slice(boundary + 2);
        boundary = buffer.indexOf('\n\n');

        if (event.error) {
          console.warn('streamTarotReply: stream error:', event.error);
          if (full.trim()) return full.trim();
          throw new ReadingFailedError(event.error);
        }
        if (event.delta) {
          full += event.delta;
          options.onDelta?.(event.delta, full);
        }
      }
    }

    if (!full.trim()) throw new ReadingFailedError('empty reply');
    return full.trim();
  } catch (error) {
    clearTimeout(timeoutId);
    if (error instanceof PaymentRequiredError || error instanceof ReadingFailedError) throw error;
    console.error('streamTarotReply: Error calling oracle:', error);
    if (full.trim()) return full.trim();
    throw new ReadingFailedError(String(error));
  }
}
